import{_ as p,a0 as d,w as l,s as n,ao as a,I as r,x as t,a1 as i,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何使用 GRUB 2 直接从硬盘运行 ISO 文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 GRUB 2 直接从硬盘运行 ISO 文件 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 GRUB 2 直接从硬盘运行 ISO 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 GRUB 2 直接从硬盘运行 ISO 文件 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150908 How to Run ISO Files Directly From the HDD with GRUB2","title":"如何使用 GRUB 2 直接从硬盘运行 ISO 文件","tag":"201510","desc":""},"relativePath":"201510/20150908 How to Run ISO Files Directly From the HDD with GRUB2.md","filePath":"[post].md"}'),u={name:"201510/20150908 How to Run ISO Files Directly From the HDD with GRUB2.md"};function m(c,e,h,f,w,b){const o=d("Link");return l(),n("div",null,[e[16]||(e[16]=a('<h1 id="如何使用-grub-2-直接从硬盘运行-iso-文件" tabindex="-1">如何使用 GRUB 2 直接从硬盘运行 ISO 文件 <a class="header-anchor" href="#如何使用-grub-2-直接从硬盘运行-iso-文件" aria-label="Permalink to “如何使用 GRUB 2 直接从硬盘运行 ISO 文件”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-featured.png" alt=""></p><p>大多数 Linux 发行版都会提供一个可以从 USB 启动的 live 环境，以便用户无需安装即可测试系统。我们可以用它来评测这个发行版或仅仅是当成一个一次性系统，并且很容易将这些文件复制到一个 U 盘上，在某些情况下，我们可能需要经常运行同一个或不同的 ISO 镜像。GRUB 2 可以配置成直接从启动菜单运行一个 live 环境，而不需要烧录这些 ISO 到硬盘或 USB 设备。</p><h3 id="获取和检查可启动的-iso-镜像" tabindex="-1">获取和检查可启动的 ISO 镜像 <a class="header-anchor" href="#获取和检查可启动的-iso-镜像" aria-label="Permalink to “获取和检查可启动的 ISO 镜像”">​</a></h3><p>为了获取 ISO 镜像，我们通常应该访问所需的发行版的网站下载与我们架构兼容的镜像文件。如果这个镜像可以从 U 盘启动，那它也应该可以从 GRUB 菜单启动。</p><p>当镜像下载完后，我们应该通过 MD5 校验检查它的完整性。这会输出一大串数字与字母合成的序列。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-md5.png" alt=""></p><p>将这个序列与下载页提供的 MD5 校验码进行比较，两者应该完全相同。</p><h3 id="配置-grub-2" tabindex="-1">配置 GRUB 2 <a class="header-anchor" href="#配置-grub-2" aria-label="Permalink to “配置 GRUB 2”">​</a></h3><p>ISO 镜像文件包含了整个系统。我们要做的仅仅是告诉 GRUB 2 哪里可以找到 kernel 和 initramdisk 或 initram 文件系统（这取决于我们所使用的发行版）。</p>',10)),r("p",null,[e[1]||(e[1]=t("在下面的例子中，一个 Kubuntu 15.04 live 环境将被配置到 Ubuntu 14.04 机器的 Grub 启动菜单项。这应该能在大多数新的以 Ubuntu 为基础的系统上运行。如果你是其它系统并且想实现一些其它的东西，你可以从",-1)),i(o,{href:"http://git.marmotte.net/git/glim/tree/grub2"},{default:s(()=>[...e[0]||(e[0]=[t("这些文件",-1)])]),_:1}),e[2]||(e[2]=t("了解更多细节，但这会要求你拥有一点 GRUB 使用经验。",-1))]),e[17]||(e[17]=a(`<p>这个例子的文件 <code>kubuntu-15.04-desktop-amd64.iso</code> 放在位于 <code>/dev/sda1</code> 的 <code>/home/maketecheasier/TempISOs/</code> 上。</p><p>为了使 GRUB 2 能正确找到它，我们应该编辑</p><pre><code>/etc/grub.d40-custom
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-40-custom-empty.png" alt=""></p><pre><code>menuentry &quot;Kubuntu 15.04 ISO&quot; {
set isofile=&quot;/home/maketecheasier/TempISOs/kubuntu-15.04-desktop-amd64.iso&quot;
loopback loop (hd0,1)$isofile
echo &quot;Starting $isofile...&quot;
linux (loop)/casper/vmlinuz.efi boot=casper iso-scan/filename=\${isofile} quiet splash
initrd (loop)/casper/initrd.lz
}
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-40-custom-new.png" alt=""></p><h3 id="分析上述代码" tabindex="-1">分析上述代码 <a class="header-anchor" href="#分析上述代码" aria-label="Permalink to “分析上述代码”">​</a></h3><p>首先设置了一个变量名 <code>$menuentry</code> ，这是 ISO 文件的所在位置 。如果你想换一个 ISO ，你应该修改 <code>isofile=&quot;/path/to/file/name-of-iso-file-.iso&quot;</code>.</p><p>下一行是指定回环设备，且必须给出正确的分区号码。</p><pre><code>loopback loop (hd0,1)$isofile
</code></pre><p>注意 hd0,1 这里非常重要，它的意思是第一硬盘，第一分区 (<code>/dev/sda1</code>)。</p><p>GRUB 的命名在这里稍微有点困惑，对于硬盘来说，它从 “0” 开始计数，第一块硬盘为 #0 ，第二块为 #1 ，第三块为 #2 ，依此类推。但是对于分区来说，它从 “1” 开始计数，第一个分区为 #1 ，第二个分区为 #2 ，依此类推。也许这里有一个很好的原因，但肯定不是明智的（明显用户体验很糟糕）..</p><p>在 Linux 中第一块硬盘，第一个分区是 <code>/dev/sda1</code> ，但在 GRUB2 中则是 <code>hd0,1</code> 。第二块硬盘，第三个分区则是 <code>hd1,3</code>, 依此类推.</p><p>下一个重要的行是：</p><pre><code>linux (loop)/casper/vmlinuz.efi boot=casper iso-scan/filename=\${isofile} quiet splash
</code></pre><p>这会载入内核镜像，在新的 Ubuntu Live CD 中，内核被存放在 <code>/casper</code> 目录，并且命名为 <code>vmlinuz.efi</code> 。如果你使用的是其它系统，可能会没有 <code>.efi</code> 扩展名或内核被存放在其它地方 (可以使用归档管理器打开 ISO 文件在 <code>/casper</code> 中查找确认)。最后一个选项， <code>quiet splash</code> ，是一个常规的 GRUB 选项，改不改无所谓。</p><p>最后</p><pre><code>initrd (loop)/casper/initrd.lz
</code></pre><p>这会载入 <code>initrd</code> ，它负责载入 RAMDisk 到内存用于启动。</p><h3 id="启动-live-系统" tabindex="-1">启动 live 系统 <a class="header-anchor" href="#启动-live-系统" aria-label="Permalink to “启动 live 系统”">​</a></h3><p>做完上面所有的步骤后，需要更新 GRUB2：</p><pre><code>sudo update-grub
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-updare-grub.png" alt=""></p><p>当重启系统后，应该可以看见一个新的、并且允许我们启动刚刚配置的 ISO 镜像的 GRUB 条目：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/07/rundirectiso-grub-menu.png" alt=""></p><p>选择这个新条目就允许我们像从 DVD 或 U 盘中启动一个 live 环境一样。</p><hr>`,27)),r("p",null,[e[4]||(e[4]=t("via: ",-1)),i(o,{href:"https://www.maketecheasier.com/run-iso-files-hdd-grub2/"},{default:s(()=>[...e[3]||(e[3]=[t("https://www.maketecheasier.com/run-iso-files-hdd-grub2/",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=t("作者：",-1)),i(o,{href:"https://www.maketecheasier.com/author/attilaorosz/"},{default:s(()=>[...e[5]||(e[5]=[t("Attila Orosz",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),i(o,{href:"https://github.com/locez"},{default:s(()=>[...e[6]||(e[6]=[t("Locez",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:s(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[13]||(e[13]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创编译，",-1)),i(o,{href:"https://linux.cn/"},{default:s(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const U=p(u,[["render",m]]);export{T as __pageData,U as default};
